import { Component, JSX, mergeProps, ParentComponent, Show } from "solid-js";

import { useDraggableContext } from "#core/ui-next/components/drag-and-drop.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { useImageCache } from "#core/ui-next/components/image-cache.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";

export interface ResourceProps extends JSX.HTMLAttributes<HTMLDivElement> {
	resourceName: string;
	resourceIcon: string;
	resourceType: string;
	resourceTypeIcon: string;
	tooltipText: string;
	resourceOrigin?: string;
	importFlag?: ImportFlagProps;
	isSwapTarget?: boolean;
}

export interface ImportFlagProps {
	primaryColor: string;
	secondaryColor: string;
}

export interface FramedResourceProps extends ResourceProps {
	showHighlight?: boolean;
	/** Must match one of the values defined in `$spacing-discrete` */
	size?: number;
}

const ImportFlagSymbol = Symbol();
const ImportFlag: Component<ImportFlagProps> = (props) => {
	const images = {
		shadowBannerCSS: "url(blp:res_banner_shadow)",
		outerBannerCSS: "url(blp:res_banner_outer)",
		innerBannerCSS: "url(blp:res_banner_inner)",
	};

	const imageCache = useImageCache();
	imageCache.registerImages(ImportFlagSymbol, Object.values(images));

	return (
		<div
			class="size-10 bg-contain bg-no-repeat bg-center absolute flex items-center justify-center -bottom-2 translate-y-1\/2"
			style={{ "background-image": images.shadowBannerCSS }}
		>
			<div
				class="size-full bg-contain bg-no-repeat bg-center absolute"
				style={{
					"background-image": images.outerBannerCSS,
					// eslint-disable-next-line solid/style-prop
					"fxs-background-image-tint": props.primaryColor,
				}}
			/>
			<div
				class="size-full bg-contain bg-no-repeat bg-center absolute"
				style={{
					"background-image": images.innerBannerCSS,
					// eslint-disable-next-line solid/style-prop
					"fxs-background-image-tint": props.secondaryColor,
				}}
			/>
		</div>
	);
};

const FramedResourceSymbol = Symbol();
export const FramedResource: ParentComponent<FramedResourceProps> = (props) => {
	const mergedProps = mergeProps({ showTooltip: true, size: 18 }, props);

	const images = {
		resourceSlotSelectCSS: "url(blp:resource_slot_select)",
	};
	const imageCache = useImageCache();
	imageCache.registerImages(FramedResourceSymbol, Object.values(images));

	const draggableContext = useDraggableContext();

	return (
		<div
			class={`size-${mergedProps.size} relative flex items-end justify-center ${draggableContext.isRenderingOverlay ? "pointer-events-none" : "pointer-events-auto"} ${props.class ?? ""}`}
			classList={{
				"mb-4": props.importFlag !== undefined,
				"mb-2": props.importFlag === undefined,
				...props.classList,
			}}
		>
			<Show when={props.importFlag}>{(importFlagProps) => <ImportFlag {...importFlagProps()} />}</Show>
			<Show when={props.showHighlight}>
				<div
					class="size-full bg-contain bg-no-repeat bg-center absolute pointer-events-none"
					style={{
						"background-image": images.resourceSlotSelectCSS,
					}}
				/>
			</Show>
			<Icon
				class="size-full pointer-events-none relative"
				isUrl={true}
				name={props.resourceIcon}
			/>
			{props.children}
			<Icon
				class="size-1\/2 -bottom-2 absolute pointer-events-none scale-90"
				name={props.resourceTypeIcon}
				isUrl={true}
				data-name="Framed-Resource"
			/>
			<Show when={props.isSwapTarget}>
				<div
					class="absolute flex flex-row items-center gap-1 px-1 py-0\.5 rounded-lg text-2xs text-white pointer-events-none"
					style={{
						border: "solid 2px rgba(255, 226, 136, 1)",
						background: "linear-gradient(to top, rgba(21, 27, 39, 1) 0%, rgba(33, 38, 57, 1) 100%)",
					}}
				>
					<Icon
						class="size-4"
						name="url(blp:replace_arrows)"
						isUrl
					/>
					<L10n.Compose text="LOC_COMMERCE_REPLACE_RESOURCE_LABEL" />
				</div>
			</Show>
		</div>
	);
};
